parameters.jsCode:
// Claude 응답에서 JSON 추출 → 시트/텔레그램용 필드로 변환
const raw = $json?.content?.[0]?.text ?? $json?.content ?? $json?.text ?? '';
let text = typeof raw === 'string' ? raw : JSON.stringify(raw);
text = text.trim().replace(/^```(?:json)?/i, '').replace(/```$/, '').trim();
const s = text.indexOf('{');
const e = text.lastIndexOf('}');
if (s !== -1 && e !== -1) text = text.slice(s, e + 1);
let d;
try { d = JSON.parse(text); } catch (err) { d = { report_markdown: (typeof raw === 'string' ? raw : text), parse_error: err.message }; }
const j = (v) => Array.isArray(v) ? v.join(', ') : (v ?? '');
const form = $('고객사 정보 입력').item.json;
return [{ json: {
  생성시각: new Date().toISOString(),
  상호명: form['상호명'],
  업종: form['업종/카테고리'],
  지역: form['지역(시/구/동)'],
  핵심키워드: d.core_keyword ?? '',
  서비스키워드: j(d.service_keywords),
  금기어: j(d.forbidden_words),
  Primary: j(d.primary_keywords),
  Secondary: j(d.secondary_keywords),
  LongTail: j(d.longtail_keywords),
  Regional: j(d.regional_keywords),
  Additional: j(d.additional_keywords),
  필수기재상단: d.top_required ?? '',
  필수기재하단: d.bottom_required ?? '',
  해시태그: j(d.hashtags),
  리포트: d.report_markdown ?? '',
  파싱오류: d.parse_error ?? ''
}}];

